begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(8);
grant usage on schema extensions to mcp_import;
grant execute on all functions in schema extensions to mcp_import;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values
('17200000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp172@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('17200000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('17200000-0000-0000-0000-000000000002','17200000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('17200000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('17200000-0000-0000-0000-000000000004','17200000-0000-0000-0000-000000000001','17200000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='17200000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('17200000-0000-0000-0000-000000000005','17200000-0000-0000-0000-000000000001','17200000-0000-0000-0000-000000000003',now());
insert into public.clients(id,organization_id,name) values ('17200000-0000-0000-0000-000000000006','17200000-0000-0000-0000-000000000002','Synthetic client');
insert into public.clients(id,organization_id,name) values ('17200000-0000-0000-0000-000000000009','17200000-0000-0000-0000-000000000002','Synthetic client');
insert into public.organizations(id,name) values ('17200000-0000-0000-0000-000000000099','Other synthetic organization');
insert into public.clients(id,organization_id,name) values ('17200000-0000-0000-0000-000000000098','17200000-0000-0000-0000-000000000099','Synthetic client');
insert into public.staffs(id,organization_id,name) values ('17200000-0000-0000-0000-000000000010','17200000-0000-0000-0000-000000000002','Synthetic staff');
set local role mcp_import;
select set_config('request.jwt.claims','{"sub":"17200000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"17200000-0000-0000-0000-000000000003","session_id":"17200000-0000-0000-0000-000000000005"}',true);
select throws_ok($$select public.search_mcp_people('17200000-0000-0000-0000-000000000002','client','Synthetic')$$,'42501','mcp_person_search_unavailable','default off rejects direct RPC');
reset role;
insert into private.mcp_person_search_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('17200000-0000-0000-0000-000000000002',true,'{}','17200000-0000-0000-0000-000000000001',now());
set local role mcp_import;
select is(jsonb_array_length(public.search_mcp_people('17200000-0000-0000-0000-000000000002','client','Synthetic')->'people'),2,'same names return both candidates');
select is(jsonb_array_length(public.search_mcp_people('17200000-0000-0000-0000-000000000002','staff','Synthetic')->'people'),1,'staff search returns match');
select is(public.search_mcp_people('17200000-0000-0000-0000-000000000002','client','Synthetic',1,0)->>'has_more','true','pagination reports more');
select is(jsonb_array_length(public.search_mcp_people('17200000-0000-0000-0000-000000000002','client','Synthetic',1,1)->'people'),1,'second page returns candidate');
select throws_ok($$select public.search_mcp_people('17200000-0000-0000-0000-000000000099','client','Synthetic')$$,'42501','mcp_person_search_unavailable','other organization denied');
reset role;
update public.organization_members set role='member' where organization_id='17200000-0000-0000-0000-000000000002' and user_id='17200000-0000-0000-0000-000000000001';
set local role mcp_import;
select is(jsonb_array_length(public.search_mcp_people('17200000-0000-0000-0000-000000000002','client','Synthetic')->'people'),0,'clients outside assigned scope hidden');
reset role;
update auth.oauth_consents set revoked_at=now() where id='17200000-0000-0000-0000-000000000004';
set local role mcp_import;
select throws_ok($$select public.search_mcp_people('17200000-0000-0000-0000-000000000002','staff','Synthetic')$$,'42501','mcp_person_search_unavailable','revoked OAuth denied');
select * from finish();
rollback;
